parameters.jsCode:
const f = $('Report Request Form').first().json;
let ai = {};
try { const m = String($json.output || '').match(/\{[\s\S]*\}/); ai = m ? JSON.parse(m[0]) : {}; } catch (e) { ai = {}; }
const pick = (k, v) => (ai[k] !== undefined && ai[k] !== null && ai[k] !== '') ? ai[k] : v;
const spec = {
  request_id: 'BPA-' + new Date().getFullYear() + '-' + String(Math.floor(1000 + Math.random() * 9000)),
  requested_by: f['Requested by'],
  requester_email: f['Requester email'],
  department: f['Department'],
  report_type: pick('report_type', f['Report type']),
  region: pick('region', f['Region']),
  date_from: pick('date_from', f['Date from']),
  date_to: pick('date_to', f['Date to']),
  aging_threshold_days: Number(pick('aging_threshold_days', f['Aging threshold (days)'] || 90)),
  priority: pick('priority', f['Priority']) === 'Urgent' ? 'Urgent' : 'Standard',
  intake_notes: Array.isArray(ai.notes) ? ai.notes : [],
  message: f['Request message'] || ''
};
if (spec.date_from > spec.date_to) [spec.date_from, spec.date_to] = [spec.date_to, spec.date_from];
return [{ json: spec }];

const s = $input.first().json;
const d = new Date(); let n = 0;
while (n < 3) { d.setDate(d.getDate() + 1); if (d.getDay() % 6 !== 0) n++; }
return [{ json: { ...s, sla_business_days: 3, sla_due: d.toISOString().slice(0, 10) } }];

// If the SQL node ran, pass its rows through. Otherwise build a seeded sample ledger (2021 onward).
if ($input.first().json.invoice_id) return $input.all();
const spec = ($('Standard SLA (3 BD)').isExecuted ? $('Standard SLA (3 BD)').first().json : $('Urgent SLA (same day)').first().json);
let seed = 20261102;
const r = () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const DAY = 864e5, today = new Date(); today.setHours(0, 0, 0, 0);
const iso = d => new Date(d).toISOString().slice(0, 10);
const FXL = { PHP: .0172, SGD: .75, INR: .0119, JPY: .0066, AUD: .66, GBP: 1.27, EUR: 1.08, PLN: .25, USD: 1, CAD: .73, MXN: .055, BRL: .19 };
const C = { APAC: [['Philippines','PHP'],['Singapore','SGD'],['India','INR'],['Japan','JPY'],['Australia','AUD']], EMEA: [['United Kingdom','GBP'],['Ireland','EUR'],['Poland','PLN']], NAM: [['United States','USD'],['Canada','CAD']], LATAM: [['Mexico','MXN'],['Brazil','BRL']] };
const SUP = [['Northwind Facilities','APAC'],['Kaito Logistics','APAC'],['Meridian Security Services','APAC'],['Pacific Rim Couriers','APAC'],['Crescent IT Staffing','APAC'],['Bayfront Catering','APAC'],['Halden Data Centers','EMEA'],['Arbor Print & Mail','EMEA'],['Sterling Legal Partners','EMEA'],['Lumen Telecom','EMEA'],['Orion Cloud Hosting','NAM'],['Vantage Consulting Group','NAM'],['Atlas Building Maintenance','NAM'],['Cobalt Software Licensing','NAM'],['Tidewell Energy','LATAM'],['Juniper Office Supply','LATAM'],['Redstone Analytics','LATAM'],['Silverline Travel','APAC']];
const BUS = ['Banking Services','Markets Operations','Technology','Corporate Real Estate','Treasury'];
const sup = SUP.map(([name, region], i) => { const cs = C[region]; const [country, cur] = cs[Math.floor(r() * cs.length)]; return { id: 'SUP-' + (1040 + i * 7), name, region, country, cur, risk: r() }; });
const rows = [];
for (let i = 0; i < 900; i++) {
  const s = sup[Math.floor(r() * sup.length)];
  const old = r() < .38, age = old ? 200 + Math.floor(r() * 1760) : Math.floor(r() * 200);
  const inv = new Date(today - age * DAY), term = [30, 45, 60][Math.floor(r() * 3)], due = new Date(+inv + term * DAY);
  const usd = Math.exp(7.6 + r() * 4.1) * (1 + s.risk * .6);
  let status, paid = null;
  if (due > today) { if (r() < .28) { status = 'Paid'; paid = new Date(+inv + Math.floor(r() * term) * DAY); } else status = 'Unpaid'; }
  else { const x = old ? r() * .68 : r() - s.risk * .18; if (x < .66) { status = 'Paid'; paid = new Date(Math.min(+today, +inv + Math.floor(term * (.6 + r() * .8)) * DAY)); } else if (x < .92) status = 'Unpaid'; else status = 'Disputed'; }
  rows.push({ invoice_id: 'INV-26' + String(400000 + i * 13), supplier_id: s.id, supplier: s.name, region: s.region, country: s.country, business_unit: BUS[Math.floor(r() * BUS.length)], invoice_date: iso(inv), due_date: iso(due), amount_local: Math.round(usd / FXL[s.cur] * 100) / 100, currency: s.cur, status, paid_date: paid ? iso(paid) : null });
}
// a few planted data defects for the Validation step
Object.keys(C).forEach((rg, k) => { const recent = rows.filter(x => x.region === rg && (today - new Date(x.invoice_date)) / DAY < 25);
  if (recent[0]) rows.push({ ...recent[0] }); if (recent[1]) recent[1].due_date = null; if (recent[2] && k === 0) recent[2].amount_local = -Math.abs(recent[2].amount_local); });
return rows.filter(x => x.invoice_date >= spec.date_from && x.invoice_date <= spec.date_to && (spec.region === 'Global' || x.region === spec.region)).map(json => ({ json }));

const FX = { PHP: .0172, SGD: .75, INR: .0119, JPY: .0066, AUD: .66, GBP: 1.27, EUR: 1.08, PLN: .25, USD: 1, CAD: .73, MXN: .055, BRL: .19 };
return $input.all().map(i => {
  const rate = FX[i.json.currency] ?? 1;
  return { json: { ...i.json, fx_rate_usd: rate, amount_usd: Math.round(Number(i.json.amount_local) * rate * 100) / 100 } };
});

const rows = $input.all().map(i => i.json);
const before = rows.reduce((a, r) => a + r.amount_usd, 0);
const seen = new Set(), clean = [], exceptions = [];
let dup = 0, missing = 0, negative = 0;
for (const r of rows) {
  if (seen.has(r.invoice_id)) { dup++; exceptions.push({ rule: 'Duplicate invoice_id', invoice_id: r.invoice_id, action: 'Removed', amount_usd: r.amount_usd }); continue; }
  seen.add(r.invoice_id);
  const x = { ...r };
  if (!x.due_date) { missing++; x.due_date = new Date(new Date(x.invoice_date).getTime() + 30 * 864e5).toISOString().slice(0, 10); exceptions.push({ rule: 'Missing due_date', invoice_id: x.invoice_id, action: 'Imputed invoice_date + 30 days', amount_usd: x.amount_usd }); }
  if (x.amount_usd < 0) { negative++; exceptions.push({ rule: 'Negative amount', invoice_id: x.invoice_id, action: 'Excluded, sent to credit-memo review', amount_usd: x.amount_usd }); continue; }
  clean.push(x);
}
const removed = exceptions.filter(e => e.action !== 'Imputed invoice_date + 30 days').reduce((a, e) => a + e.amount_usd, 0);
const after = clean.reduce((a, r) => a + r.amount_usd, 0);
const variance = Math.round((before - removed - after) * 100) / 100;
return [{ json: {
  passed: clean.length > 0 && variance === 0,
  rows_in: rows.length, rows_out: clean.length,
  checks: { duplicate_ids: dup, missing_due_dates: missing, negative_amounts: negative, control_total_variance: variance },
  exceptions, rows: clean
} }];

