Rows in: {{ $json.rows_in }} · rows out: {{ $json.rows_out }}

parameters.jsCode:
const spec = ($('Standard SLA (3 BD)').isExecuted ? $('Standard SLA (3 BD)').first().json : $('Urgent SLA (same day)').first().json);
const rows = $json.rows;
const today = new Date(); today.setHours(0, 0, 0, 0);
const dpd = r => Math.max(0, Math.floor((today - new Date(r.due_date)) / 864e5));
const B = ['Current', '1-30', '31-60', '61-90', '90+'];
const bk = d => d <= 0 ? 0 : d <= 30 ? 1 : d <= 60 ? 2 : d <= 90 ? 3 : 4;
const open = rows.filter(r => r.status !== 'Paid').map(r => ({ ...r, days_past_due: dpd(r), aging_bucket: B[bk(dpd(r))] }));
const sum = (a, f) => a.reduce((t, x) => t + f(x), 0);
const regions = [...new Set(open.map(r => r.region))].sort();
const aging = regions.map(rg => { const v = [0, 0, 0, 0, 0]; open.filter(r => r.region === rg).forEach(r => v[bk(r.days_past_due)] += r.amount_usd);
  return { region: rg, ...Object.fromEntries(B.map((b, i) => [b, Math.round(v[i])])), total: Math.round(v.reduce((a, b) => a + b, 0)) }; });
const overdue = open.filter(r => r.days_past_due > 0);
const flagged = open.filter(r => r.days_past_due > spec.aging_threshold_days).sort((a, b) => b.days_past_due - a.days_past_due);
const paid = rows.filter(r => r.status === 'Paid');
const by = {};
open.forEach(r => { const o = by[r.supplier] || (by[r.supplier] = { supplier: r.supplier, region: r.region, open_invoices: 0, open_usd: 0, overdue_usd: 0, max_days_past_due: 0, disputed: 0 });
  o.open_invoices++; o.open_usd += r.amount_usd; if (r.days_past_due > 0) o.overdue_usd += r.amount_usd; o.max_days_past_due = Math.max(o.max_days_past_due, r.days_past_due); if (r.status === 'Disputed') o.disputed++; });
const suppliers = Object.values(by).map(o => { const score = Math.max(0, Math.round(100 - (o.overdue_usd / Math.max(o.open_usd, 1)) * 55 - Math.min(o.max_days_past_due, 180) / 180 * 30 - (o.disputed ? 15 : 0)));
  return { ...o, open_usd: Math.round(o.open_usd), overdue_usd: Math.round(o.overdue_usd), health_score: score, band: score >= 70 ? 'Healthy' : score >= 45 ? 'Watch' : 'At Risk' }; })
  .sort((a, b) => b.open_usd - a.open_usd).slice(0, 10);
const by_business_unit = [...new Set(open.map(r => r.business_unit))].map(b => ({ business_unit: b, open_usd: Math.round(sum(open.filter(r => r.business_unit === b), r => r.amount_usd)) })).sort((a, b) => b.open_usd - a.open_usd);
const openUsd = sum(open, r => r.amount_usd), overUsd = sum(overdue, r => r.amount_usd);
const kpis = {
  open_invoices: open.length, open_usd: Math.round(openUsd), overdue_usd: Math.round(overUsd),
  overdue_share: openUsd ? +(overUsd / openUsd).toFixed(3) : 0,
  avg_days_past_due: overdue.length ? Math.round(sum(overdue, r => r.days_past_due) / overdue.length) : 0,
  flagged_invoices: flagged.length, flagged_usd: Math.round(sum(flagged, r => r.amount_usd)),
  disputed_invoices: open.filter(r => r.status === 'Disputed').length,
  on_time_payment_rate: paid.length ? +(paid.filter(r => r.paid_date <= r.due_date).length / paid.length).toFixed(3) : null,
  suppliers_at_risk: suppliers.filter(s => s.band === 'At Risk').length
};
return [{ json: { spec, data_quality: $json.checks, kpis, aging_by_region: aging, supplier_health: suppliers, by_business_unit, flagged } }];

